    fault = 1;
}
if (!fault) {
    if (md_config.on_cycles < 1 || md_config.on_cycles > 100) fault = 1;
    if (md_config.rest_cycles < 1 || md_config.rest_cycles > 100) fault = 1;
    if (!isfinite(md_config.gain_s_inv) || md_config.gain_s_inv < 0.0) fault = 1;
    if (!isfinite(md_config.max_dipole_a_m2) || md_config.max_dipole_a_m2 < 0.0) fault = 1;
    if (!isfinite((double)md_config.extra_rest_per_saturated_cycle) || 
        md_config.extra_rest_per_saturated_cycle > 100) fault = 1;
}
