    md_state.mode = MD_FAULT;
    md_output.mode = MD_FAULT;
    md_output.elapsed = 0;
    md_output.saturation_mask = 0;
    md_output.dipole_a_m2.x = 0.0; md_output.dipole_a_m2.y = 0.0; md_output.dipole_a_m2.z = 0.0;
