md_output.torque_nm.x = 0.0; md_output.torque_nm.y = 0.0; md_output.torque_nm.z = 0.0;
md_output.dissipative_power = 0.0;

adcs_actuator_command_t cmd;
adcs_vec3_t achievable_torque;

// Determine active mode and update state
md_mode_t active_mode = md_state.mode;

if (md_input.enable == FALSE32 || md_input.demand == FALSE32) {
    md_state.mode = MD_IDLE;
    md_state.elapsed = 0;
    md_state.saturated_on_cycles = 0;
    active_mode = MD_IDLE;
} else {
    switch (md_state.mode) {
        case MD_IDLE:
            md_state.mode = MD_ON;
            md_state.elapsed = 1;
            md_state.saturated_on_cycles = 0;
            active_mode = MD_ON;
            break;
        case MD_ON:
