                md_state.mode = MD_REST;
                md_state.elapsed = 0;
                md_state.saturated_on_cycles = 0;
                md_state.rest_target = md_config.rest_cycles + md_config.extra_rest_per_saturated_cycle * md_state.saturated_on_cycles;
                // active_mode remains ON
            } else {
                md_state.elapsed++;
                // active_mode remains ON
            }
            break;
        case MD_REST:
