            md_state.elapsed++;
            if (md_state.elapsed >= md_state.rest_target) {
                md_state.mode = MD_IDLE;
                md_state.elapsed = 0;
                // active_mode remains REST
            }
            // active_mode remains REST
            break;
        default:
            break;
    }
}

md_output.mode = active_mode;
md_output.elapsed = md_state.elapsed;

