// Step 1: Input and Configuration Validation
if (md_input.momentum_nms == NULL || md_input.field_body_t == NULL) {
    md_state.mode = MD_FAULT;
    md_output.mode = MD_FAULT;
    md_output.elapsed = 0;
    md_output.saturation_mask = 0;
    md_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    md_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    md_output.dissipative_power = 0.0;
    return;
}

int config_valid = (md_config.on_cycles >= 1 && md_config.on_cycles <= 100) &&
                   (md_config.rest_cycles >= 1 && md_config.rest_cycles <= 100) &&
                   isfinite(md_config.gain_s_inv) && md_config.gain_s_inv >= 0.0 &&
                   isfinite(md_config.max_dipole_a_m2) && md_config.max_dipole_a_m2 >= 0.0 &&
                   isfinite((double)md_config.extra_rest_per_saturated_cycle) &&
                   ((double)md_config.extra_rest_per_saturated_cycle <= 100.0);

int telemetry_valid = adcs_is_finite_vec3(md_input.momentum_nms) && adcs_is_finite_vec3(md_input.field_body_t);

if (!config_valid || !telemetry_valid) {
    md_state.mode = MD_FAULT;
    md_output.mode = MD_FAULT;
    md_output.elapsed = 0;
    md_output.saturation_mask = 0;
    md_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    md_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    md_output.dissipative_power = 0.0;
    return;
}

// Step 2: Handle Fault State
if (md_state.mode == MD_FAULT) {
    md_output.mode = MD_FAULT;
    md_output.elapsed = 0;
    md_output.saturation_mask = 0;
    md_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    md_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    md_output.dissipative_power = 0.0;
    return;
}

// Step 3: Determine Demand Presence
int demand_present = (md_input.enable != 0) && (md_input.demand != 0);

if (!demand_present) {
    // Disabled or demand absent -> Force IDLE
    md_state.mode = MD_IDLE;
    md_state.elapsed = 0;
    md_state.saturated_on_cycles = 0;

    md_output.mode = MD_IDLE;
    md_output.elapsed = 0;
    md_output.saturation_mask = 0;
    md_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
    md_output.torque_nm = (adcs_vec3_t){0, 0, 0};
    md_output.dissipative_power = 0.0;
} else {
    switch (md_state.mode) {
        case MD_IDLE:
            // Demand begins in IDLE -> Transition to ON
            md_state.mode = MD_ON;
            md_state.elapsed = 0;

            // Compute ON cycle outputs
            adcs_actuator_command_t cmd;
            adcs_momentum_unload_dipole(
                md_input.momentum_nms,
                md_input.field_body_t,
                md_config.gain_s_inv,
                md_config.max_dipole_a_m2,
                &cmd,
                &md_output.torque_nm
            );

            md_output.mode = MD_ON;
            md_output.elapsed = 1;
            md_output.saturation_mask = cmd.saturated_axes;
            md_output.dipole_a_m2 = cmd.command;
            md_output.dissipative_power = adcs_vec3_dot(&md_output.torque_nm, md_input.momentum_nms);
            break;

        case MD_ON:
            md_state.elapsed++;

            if (md_state.elapsed >= md_config.on_cycles) {
                // Exactly on_cycles reached -> Transition to REST
                md_state.mode = MD_REST;
                md_state.elapsed = 0;

                // Calculate REST duration for this burst
                double extra = (double)md_state.saturated_on_cycles * (double)md_config.extra_rest_per_saturated_cycle;
                md_state.rest_target = md_config.rest_cycles + (unint32)extra;

                // Reset saturation counter for next burst
                md_state.saturated_on_cycles = 0;

                md_output.mode = MD_REST;
                md_output.elapsed = 0;
                md_output.saturation_mask = 0;
                md_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
                md_output.torque_nm = (adcs_vec3_t){0, 0, 0};
                md_output.dissipative_power = 0.0;
            } else {
                // Still within ON cycles
                adcs_actuator_command_t cmd;
                adcs_momentum_unload_dipole(
                    md_input.momentum_nms,
                    md_input.field_body_t,
                    md_config.gain_s_inv,
                    md_config.max_dipole_a_m2,
                    &cmd,
                    &md_output.torque_nm
                );

                md_output.mode = MD_ON;
                md_output.elapsed = md_state.elapsed;
                md_output.saturation_mask = cmd.saturated_axes;
                md_output.dipole_a_m2 = cmd.command;

                // Increment saturated cycle counter if mask is nonzero
                if (cmd.saturated_axes != 0) {
                    md_state.saturated_on_cycles++;
                }

                md_output.dissipative_power = adcs_vec3_dot(&md_output.torque_nm, md_input.momentum_nms);
            }
            break;

        case MD_REST:
            md_state.elapsed++;

            if (md_state.elapsed >= md_state.rest_target) {
                // Exactly rest_target reached -> Transition to IDLE
                md_state.mode = MD_IDLE;
                md_state.elapsed = 0;

                md_output.mode = MD_IDLE;
                md_output.elapsed = 0;
                md_output.saturation_mask = 0;
                md_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
                md_output.torque_nm = (adcs_vec3_t){0, 0, 0};
                md_output.dissipative_power = 0.0;
            } else {
                // Still within REST duration
                md_output.mode = MD_REST;
                md_output.elapsed = md_state.elapsed;
                md_output.saturation_mask = 0;
                md_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
                md_output.torque_nm = (adcs_vec3_t){0, 0, 0};
                md_output.dissipative_power = 0.0;
            }
            break;

        default:
            // Invalid state, force fault
            md_state.mode = MD_FAULT;
            md_output.mode = MD_FAULT;
            md_output.elapsed = 0;
            md_output.saturation_mask = 0;
            md_output.dipole_a_m2 = (adcs_vec3_t){0, 0, 0};
            md_output.torque_nm = (adcs_vec3_t){0, 0, 0};
            md_output.dissipative_power = 0.0;
            break;
    }
}

