if (md_config.on_cycles < 1 || md_config.on_cycles > 100) valid_config = 0;
if (md_config.rest_cycles < 1 || md_config.rest_cycles > 100) valid_config = 0;

if (!valid_config) {
    md_state.mode = MD_FAULT;
    md_state.elapsed = 0;
    md_state.saturated_on_cycles = 0;
    md_output.mode = MD_FAULT;
    md_output.elapsed = 0;
    md_output.saturation_mask = 0;
    md_output.dipole_a_m2.x = 0; md_output.dipole_a_m2.y = 0; md_output.dipole_a_m2.z = 0;
    md_output.torque_nm.x = 0; md_output.torque_nm.y = 0; md_output.torque_nm.z = 0;
    md_output.dissipative_power = 0;
    return;
}

// Check for finite telemetry
if (!adcs_is_finite_vec3(md_input.momentum_nms) || !adcs_is_finite_vec3(md_input.field_body_t)) {
     md_state.mode = MD_FAULT;
     md_state.elapsed = 0;
     md_state.saturated_on_cycles = 0;
     md_output.mode = MD_FAULT;
     md_output.elapsed = 0;
     md_output.saturation_mask = 0;
     md_output.dipole_a_m2.x = 0; md_output.dipole_a_m2.y = 0; md_output.dipole_a_m2.z = 0;
     md_output.torque_nm.x = 0; md_output.torque_nm.y = 0; md_output.torque_nm.z = 0;
     md_output.dissipative_power = 0;
     return;
}

// Handle Fault State Recovery or Initial Transition to IDLE
if (md_state.mode == MD_FAULT) {
    md_state.mode = MD_IDLE;
    md_state.elapsed = 0;
    md_state.saturated_on_cycles = 0;
    md_state.rest_target = 0;
}

adcs_actuator_command_t cmd;
adcs_vec3_t zero_vec = {0, 0, 0};
cmd.command = zero_vec;
cmd.saturated_axes = 0;

// Mode Logic
switch (md_state.mode) {
    case MD_IDLE:
        if (md_input.enable && md_input.demand) {
            // Transition to ON
            md_state.mode = MD_ON;
            md_state.elapsed = 1;

            // Compute outputs for this ON cycle
            adcs_status_t status_on_init = adcs_momentum_unload_dipole(
                md_input.momentum_nms, 
                md_input.field_body_t, 
                md_config.gain_s_inv, 
                md_config.max_dipole_a_m2, 
                &cmd, 
                &md_output.torque_nm
            );
            if (status_on_init != ADCS_OK) {
                md_state.mode = MD_FAULT;
                md_state.elapsed = 0;
                md_state.saturated_on_cycles = 0;
                md_output.mode = MD_FAULT;
                md_output.elapsed = 0;
                md_output.saturation_mask = 0;
                md_output.dipole_a_m2.x = 0; md_output.dipole_a_m2.y = 0; md_output.dipole_a_m2.z = 0;
                md_output.torque_nm.x = 0; md_output.torque_nm.y = 0; md_output.torque_nm.z = 0;
                md_output.dissipative_power = 0;
                return;
            }

            md_output.dipole_a_m2 = cmd.command;
            md_output.saturation_mask = cmd.saturated_axes;
            md_output.dissipative_power = adcs_vec3_dot(&md_output.torque_nm, md_input.momentum_nms);
            md_output.mode = MD_ON;
            md_output.elapsed = md_state.elapsed;
        } else {
            // Stay in IDLE
            md_state.mode = MD_IDLE;
            md_state.elapsed = 0;
            md_output.mode = MD_IDLE;
            md_output.elapsed = 0;
            md_output.saturation_mask = 0;
            md_output.dipole_a_m2 = zero_vec;
            md_output.torque_nm = zero_vec;
            md_output.dissipative_power = 0;
        }
        break;

    case MD_ON:
        // Recompute outputs
        adcs_status_t status_on_loop = adcs_momentum_unload_dipole(
            md_input.momentum_nms, 
            md_input.field_body_t, 
            md_config.gain_s_inv, 
            md_config.max_dipole_a_m2, 
            &cmd, 
            &md_output.torque_nm
        );
        if (status_on_loop != ADCS_OK) {
            md_state.mode = MD_FAULT;
            md_state.elapsed = 0;
            md_state.saturated_on_cycles = 0;
            md_output.mode = MD_FAULT;
            md_output.elapsed = 0;
            md_output.saturation_mask = 0;
            md_output.dipole_a_m2.x = 0; md_output.dipole_a_m2.y = 0; md_output.dipole_a_m2.z = 0;
            md_output.torque_nm.x = 0; md_output.torque_nm.y = 0; md_output.torque_nm.z = 0;
            md_output.dissipative_power = 0;
            return;
        }

        md_output.dipole_a_m2 = cmd.command;
        md_output.saturation_mask = cmd.saturated_axes;
        md_output.dissipative_power = adcs_vec3_dot(&md_output.torque_nm, md_input.momentum_nms);

        // Update saturation counter
        if (cmd.saturated_axes != 0) {
            md_state.saturated_on_cycles++;
        }

        // Check if ON cycles complete
        if (md_state.elapsed >= md_config.on_cycles) {
            // Calculate REST duration
            md_state.rest_target = md_config.rest_cycles + md_state.saturated_on_cycles * md_config.extra_rest_per_saturated_cycle;
            md_state.saturated_on_cycles = 0; // Reset for next burst

            // Transition to REST for NEXT call
            md_state.mode = MD_REST;
            md_state.elapsed = 0; // Elapsed resets on transition

            // Output for THIS call is still ON
            md_output.mode = MD_ON;
            md_output.elapsed = md_state.elapsed;
        } else {
            md_output.mode = MD_ON;
            md_output.elapsed = md_state.elapsed;
            md_state.elapsed++;
        }
        break;

    case MD_REST:
        // Zero output
        md_output.mode = MD_REST;
        md_output.elapsed = md_state.elapsed;
        md_output.saturation_mask = 0;
        md_output.dipole_a_m2 = zero_vec;
        md_output.torque_nm = zero_vec;
        md_output.dissipative_power = 0;

        // Check if REST cycles complete
        if (md_state.elapsed >= md_state.rest_target) {
            md_state.mode = MD_IDLE;
            md_state.elapsed = 0;
        } else {
            md_state.elapsed++;
        }
        break;

    default:
        // Fallback to IDLE
        md_state.mode = MD_IDLE;
        md_state.elapsed = 0;
        md_output.mode = MD_IDLE;
        md_output.elapsed = 0;
        md_output.saturation_mask = 0;
        md_output.dipole_a_m2 = zero_vec;
        md_output.torque_nm = zero_vec;
        md_output.dissipative_power = 0;
        break;
}
